text = subprocess.run(['pdftotext', '/home/ubuntu/.agent-ml-research-idea_gen_0509_14/projects/distill_sparse_swiglu/paper/main.pdf', '-'], capture_output=True, text=True).stdout
pages = text.split('\f')
for i, page in enumerate(pages[:12], 1):
    content = page.strip()
    has_conclusion = 'Conclusion' in content and ('KL distillation discovers' in content or 'diverge 68' in content)
    has_limitation = 'Limitations' in content
    has_ethics = 'Ethics Statement' in content
    has_refs = 'References' in content and 'Shazeer' in content
    markers = []
    if has_conclusion: markers.append('CONCLUSION')
    if has_limitation: markers.append('LIMITATIONS')
    if has_ethics: markers.append('ETHICS')
    if has_refs: markers.append('REFERENCES')
    if markers:
        print(f"Page {i}: {', '.join(markers)}")

    # Also check for section headers
    for line in content.split('\n'):
        stripped = line.strip()
        if stripped in ['5 Conclusion', '6 Conclusion', 'Conclusion', 'Limitations', 'Ethics Statement', 'References']:
            print(f"  -> Section '{stripped}' on page {i}")
